file.content:
[
  {
    "id": "c001",
    "name": "Preliminary Statement — Parties",
    "text": "This POOLING AND SERVICING AGREEMENT, dated as of June 1, 2007, is among BEAR STEARNS ASSET BACKED SECURITIES I LLC, a Delaware limited liability company, as depositor (the “Depositor’), WELLS FARGO BANK, NATIONAL ASSOCIATION, a national banking association, as master servicer (in such capacity, the “Master Servicer’) and as securities administrator (in such capacity, the “Securities Administrator”), and DEUTSCHE BANK NATIONAL TRUST COMPANY, a national banking association, as trustee (the “Trustee”)."
  },
  {
    "id": "c002",
    "name": "Preliminary Statement — Trust Fund ownership",
    "text": "PRELIMINARY STATEMENT The Depositor is the owner of the Trust Fund that is hereby conveyed to the Trustee in return for the Certificates."
  },
  {
    "id": "c003",
    "name": "REMIC I election",
    "text": "REMIC I As provided herein, the Securities Administrator on behalf of the Trustee shall elect to treat the segregated pool of assets consisting of the Mortgage Loans and certain other related assets subject to this Agreement (other than the Reserve Fund, the Yield Maintenance Agreement, the Yield Maintenance Collateral Account and any Prepayment Charge Waiver Amounts and, for the avoidance of doubt, the Supplemental Interest Trust, the Swap Agreement, the Swap Account, the Swap Collateral Account and any rights or obligations in respect of the Swap Administration Agreement) as a REMIC for federal income tax purposes, and such segregated pool of assets will be designated as “REMIC I”."
  },
  {
    "id": "c004",
    "name": "REMIC I Residual Interest",
    "text": "The Class R-1 Certificates will represent the sole class of Residual Interests in REMIC I for purposes of the REMIC Provisions."
  },
  {
    "id": "c005",
    "name": "REMIC I Regular Interests",
    "text": "The following table irrevocably sets forth the designation, the Uncertificated REMIC I Pass- Through Rate, the initial Uncertificated Principal Balance and, for purposes of satisfying Treasury Regulation Section 1.860G-1(a)(4)(iii), the “latest possible maturity date” for each of the REMIC I Regular Interests. None of the REMIC I Regular Interests will be certificated."
  },
  {
    "id": "c006",
    "name": "REMIC I latest possible maturity date",
    "text": "For purposes of Section 1.860G-1(a)(4)(iii) of the Treasury Regulations, the Distribution Date in the month following the maturity date for the Mortgage Loan with the latest maturity date has been designated as the “latest possible maturity date” for each REMIC I Regular Interest."
  },
  {
    "id": "c007",
    "name": "REMIC I Pass-Through Rate calculation",
    "text": "Calculated in accordance with the definition of “Uncertificated REMIC I Pass-Through Rate” herein."
  },
  {
    "id": "c008",
    "name": "REMIC II election",
    "text": "REMIC II As provided herein, the Securities Administrator on behalf of the Trustee shall elect to treat the segregated pool of assets consisting of the REMIC I Regular Interests as a REMIC for federal income tax purposes, and such segregated pool of assets will be designated as “REMIC IT”."
  },
  {
    "id": "c009",
    "name": "REMIC II Residual Interest",
    "text": "The Class R-2 Certificates will represent the sole class of Residual Interests in REMIC II for purposes of the REMIC Provisions."
  },
  {
    "id": "c010",
    "name": "REMIC II Regular Interests",
    "text": "The following table irrevocably sets forth the designation, the Uncertificated REMIC II Pass-Through Rate, the initial Uncertificated Principal Balance and, for purposes of satisfying Treasury Regulation Section 1.860G-1(a)(4)(ii), the “latest possible maturity date” for each of the REMIC II Regular Interests. None of the REMIC II Regular Interests will be certificated."
  },
  {
    "id": "c011",
    "name": "REMIC II latest possible maturity date",
    "text": "For purposes of Section 1.860G-1(a)(4)(iii) of the Treasury Regulations, the Distribution Date in the month following the maturity date for the Mortgage Loan with the latest maturity date has been designated as the “latest possible maturity date” for each REMIC II Regular Interest."
  },
  {
    "id": "c012",
    "name": "REMIC II Pass-Through Rate calculation",
    "text": "Calculated in accordance with the definition of “Uncertificated REMIC II Pass-Through Rate” herein."
  },
  {
    "id": "c013",
    "name": "REMIC II Regular Interest IO notional amount",
    "text": "REMIC II Regular Interest IO will not have an Uncertificated Principal Balance but will accrue interest on its uncertificated notional amount calculated in accordance with the definition of “Uncertificated Notional Amount” herein."
  },
  {
    "id": "c014",
    "name": "REMIC III election",
    "text": "REMIC II] As provided herein, the Securities Administrator on behalf of the Trustee shall elect to treat the segregated pool of assets consisting of the REMIC II Regular Interests as a REMIC for federal income tax purposes, and such segregated pool of assets will be designated as “REMIC II”."
  },
  {
    "id": "c015",
    "name": "REMIC III Residual Interest",
    "text": "The Class R-3 Certificates will represent the sole class of Residual Interests in REMIC II for purposes of the REMIC Provisions."
  },
  {
    "id": "c016",
    "name": "REMIC III Regular Interests",
    "text": "The following table irrevocably sets forth the designation, Pass-Through Rate, Initial Certificate Principal Balance (or initial Uncertificated Principal Balance, in the case of the Class CE Interest, Class P Interest or Class IO Interest) and, for purposes of satisfying Treasury Regulation Section 1.860G-1(a)(4)(iii), the “latest possible maturity date” for each class of Certificates and interests that represents ownership of Regular Interests in REMIC III created hereunder."

  "text": "The following table irrevocably sets forth the designation, Pass-Through Rate, Initial Certificate Principal Balance (or initial Uncertificated Principal Balance, in the case of the Class CE Interest, Class P Interest or Class IO Interest) and, for purposes of satisfying Treasury Regulation Section 1.860G-1(a)(4)(iii), the “latest possible maturity date” for each class of Certificates and interests that represents ownership of Regular Interests in REMIC III created hereunder."
},
{
  "id": "c017",
  "name": "REMIC III Certificate rights and obligations",
  "text": "Each Certificate, other than the Class P, Class CE and Class R Certificates, represents ownership of a Regular Interest in REMIC III and also represents (i) the right to receive certain amounts specified herein in respect of Basis Risk Shortfall Carry Forward Amounts and (ii) the obligation to pay Class JO Distribution Amounts. The entitlement to principal of the Regular Interest which corresponds to each Certificate shall be equal in amount and timing to the entitlement to principal of such Certificate."
},
{
  "id": "c018",
  "name": "REMIC III latest possible maturity date",
  "text": "aH For purposes of Section 1.860G-1(a)(4)(iii) of the Treasury Regulations, the Distribution Date in the month following the maturity date for the Mortgage Loan with the latest maturity date has been designated as the “atest possible maturity date” for each Class of Class A, Class M and Class B Certificates and the Class CE Interest and the Class P Interest."
},
{
  "id": "c019",
  "name": "REMIC III Regular Interest distributions",
  "text": "This Class of Certificates represents ownership of a Regular Interest in REMIC III. Any amount distributed on this Class of Certificates on any Distribution Date in excess of the amount distributable on the related Regular Interest in REMIC III on such Distribution Date shall be treated for federal income tax purposes as having been paid from the Reserve Fund or the Supplemental Interest Trust, as applicable, and any amount distributable on the related Regular Interest in REMIC III on such Distribution Date in excess of the amount distributable on such Class of Certificates on such Distribution Date shall be treated for such purposes as having been distributed to the Holders of such Certificates and then paid by such Holders to the Supplemental Interest Trust, all pursuant to and as further provided in Section 4.22 hereof."
},
{
  "id": "c020",
  "name": "REMIC III corresponding Pass-Through Rates",
  "text": "Each Regular Interest in REMIC III which corresponds to a Class A, Class M or Class B Certificate will have the same Pass-Through Rate as such Certificate, except with respect to the Net Rate Cap. The Net Rate Cap for each such Regular Interest in REMIC III and Certificate is specified in the definition of “Net Rate Cap.”"
},
{
  "id": "c021",
  "name": "Class CE Interest accrual",
  "text": "4) The Class CE Interest will not accrue interest on its Uncertificated Principal Balance, but will accrue interest at the Class CE Pass-Through Rate on its Uncertificated Notional Amount, which shall equal the aggregate Uncertificated Principal Balance of the REMIC II Regular Interests (other than REMIC II Regular Interest P)."
},
{
  "id": "c022",
  "name": "Class IO Interest principal balance",
  "text": "For federal income tax purposes, the Class IO Interest will not have an Uncertificated Principal Balance, but will have a notional amount equal to the Uncertificated Notional Amount for REMIC II Regular Interest IO."
},
{
  "id": "c023",
  "name": "Class IO Interest distributions",
  "text": "6) For federal income tax purposes, the Class IO Interest will not have a Pass-Through Rate, but will be entitled to 100% of the amounts distributed on REMIC II Regular Interest IO."
},
{
  "id": "c024",
  "name": "REMIC IV election and Residual Interest",
  "text": "REMIC IV 6 [TPW: NYLEGAL:691857.8] 17297-00533 11/15/2007 06:00 PM As provided herein, the Securities Administrator on behalf of the Trustee shall elect to treat the segregated pool of assets consisting of the Class CE Interest as a REMIC for federal income tax purposes, and such segregated pool of assets will be designated as “REMIC IV”. The Class R-4 Interest will represent the sole class of Residual Interests in REMIC [V for purposes of the REMIC Provisions."
},
{
  "id": "c025",
  "name": "REMIC IV Regular Interest",
  "text": "The following table sets forth the Class designation, Pass-Through Rate, Initial Certificate Principal Balance and, for purposes of satisfying Treasury Regulation Section 1.860G-1(a)(4)(ii1), the “latest possible maturity date” for the indicated Class of Certificates that represents a Regular Interest in REMIC IV created hereunder:"
},
{
  "id": "c026",
  "name": "REMIC IV latest possible maturity date",
  "text": "0) For purposes of Section 1.860G-1(a)(4)(iii) of the Treasury Regulations, the Distribution Date in the month following the maturity date for the Mortgage Loan with the latest maturity date has been designated as the “latest possible maturity date” for the Class CE Certificates."
},
{
  "id": "c027",
  "name": "Class CE Certificate distributions",
  "text": "2) The Class CE Certificates will receive 100% of the amounts received in respect of the Class CE Interest."
},
{
  "id": "c028",
  "name": "REMIC V election and Residual Interest",
  "text": "REMIC V. As provided herein, the Securities Administrator on behalf of the Trustee shall elect to treat the segregated pool of assets consisting of the Class P Interest as a REMIC for federal income tax purposes, and such segregated pool of assets will be designated as “REMIC V”. The Class R-5 Interest will represent the sole class of Residual Interests in REMIC V for purposes of the REMIC Provisions."
},
{
  "id": "c029",
  "name": "REMIC V Regular Interest",
  "text": "The following table sets forth the Class designation, Pass-Through Rate, Initial Certificate Principal Balance and, for purposes of satisfying Treasury Regulation Section 1.860G-1(a)(4)Gii), the “latest possible maturity date” for the indicated Class of Certificates that represents a Regular Interest in REMIC V created hereunder:"
},
{
  "id": "c030",
  "name": "REMIC V latest possible maturity date",
  "text": "(2) For purposes of Section 1.860G-1(a)(4)(iii) of the Treasury Regulations, the Distribution Date in the month following the maturity date for the Mortgage Loan with the latest maturity date has been designated as the “atest possible maturity date” for the Class P Certificates."
},
{
  "id": "c031",
  "name": "Class P Certificate distributions",
  "text": "The Class P Certificates will receive 100% of the amounts received in respect of the Class P Interest."
},
{
  "id": "c032",
  "name": "REMIC VI election and Residual Interest",
  "text": "REMIC VI As provided herein, the Securities Administrator on behalf of the Trustee shall elect to treat the segregated pool of assets consisting of the Class IO Interest as a REMIC for federal income tax purposes, and such segregated pool of assets will be designated as “REMIC VI”. The Class R-6 Interest will represent the sole class of Residual Interests in REMIC VI for purposes of the REMIC Provisions."
},
{
  "id": "c033",
  "name": "REMIC VI Regular Interest",
  "text": "The following table sets forth the designation, Pass-Through Rate, initial Uncertificated Principal Balance and, for purposes of satisfying Treasury Regulation Section 1.860G- 1(a)(4)(iii), the “latest possible maturity date” for the indicated class of interests that represents a Regular Interest in REMIC VI created hereunder:"
},
{
  "id": "c034",
  "name": "REMIC VI latest possible maturity date",
  "text": "For purposes of Section 1.860G-1(a)(4)(iii) of the Treasury Regulations, the Distribution Date in the month following the maturity date for the Mortgage Loan with the latest maturity date has been designated as the “latest possible maturity date” for REMIC VI Regular Interest IO."
},
{
  "id": "c035",
  "name": "REMIC VI Regular Interest JO ownership",
  "text": "REMIC VI Regular Interest JO will be held as an asset of the Supplemental Interest Trust."
},
{
  "id": "c036",
  "name": "REMIC VI Regular Interest IO distributions",
  "text": "REMIC VI Regular Interest IO will not have a Pass-Through Rate, but will receive 100% of the amounts received in respect of the Class IO Interest."
},
{
  "id": "c037",
  "name": "REMIC VI Regular Interest JO notional amount",
  "text": "REMIC VI Regular Interest JO will not have an Uncertificated Principal Balance, but will have a notional amount equal to the Uncertificated Notional Amount for the Class IO Interest."
},
{
  "id": "c038",
  "name": "Trust and Certificate names",
  "text": "The Trust Fund shall be named, and may be referred to as, the “Morgan Stanley Structured Trust I 2007-1.” The Certificates issued hereunder may be referred to as “Asset- Backed Certificates Series 2007-1” (including for purposes of any endorsement or assignment of a Mortgage Note or Mortgage)."
},
{
  "id": "c039",
  "name": "1.01 Defined Terms",
  "text": "ARTICLE I DEFINITIONS Section 1:01 Defined Terms. Whenever used in this Agreement, the following words and phrases, unless the context otherwise requires, shall have the following meanings:"
},
{
  "id": "c040",
  "name": "Accepted Master Servicing Practices",
  "text": "Accepted Master Servicing Practices: With respect to any Mortgage Loan, those customary mortgage servicing practices of prudent mortgage servicing institutions that master service mortgage loans of the same type and quality as such Mortgage Loan in the jurisdiction where the related Mortgaged Property is located, to the extent applicable to the Trustee or the Master Servicer (except in its capacity as successor to a Servicer)."
},
{
  "id": "c041",
  "name": "Account",
  "text": "Account: The Distribution Account, the Swap Account, the Swap Collateral Account, the Class P Certificate Account, the Yield Maintenance Collateral Account, the Reserve Fund and any Protected Account."
},
{
  "id": "c042",
  "name": "Accredited",
  "text": "Accredited: Accredited Home Lenders, Inc."
},
{
  "id": "c043",
  "name": "Additional Disclosure",
  "text": "Additional Disclosure: As defined in Section 4.18."
},
{
  "id": "c044",
  "name": "Additional Form 10-D Disclosure",
  "text": "Additional Form 10-D Disclosure: As defined in Section 4.18."
},
{
  "id": "c045",
  "name": "Additional Form 10-K Disclosure",
  "text": "Additional Form 10-K Disclosure: As defined in Section 4.18."
},
{
  "id": "c046",
  "name": "Adjustable Rate Mortgage Loan",
  "text": "Adjustable Rate Mortgage Loan: Each of the Mortgage Loans identified in the Mortgage Loan Schedule as having a Mortgage Rate that is subject to adjustment."
},
{
  "id": "c047",
  "name": "Adjustment Date",
  "text": "Adjustment Date: With respect to each Adjustable Rate Mortgage Loan, the first day of the month in which the Mortgage Rate of an Adjustable Rate Mortgage Loan changes pursuant to the related Mortgage Note. The first Adjustment Date following the Cut-off Date as to each Adjustable Rate Mortgage Loan is set forth in the Mortgage Loan Schedule."
},
{
  "id": "c048",
  "name": "Advance",
  "text": "Advance: An advance of delinquent payments of principal or interest in respect of a Mortgage Loan required to be made by the related Servicer in accordance with the related Servicing Agreement or by the Master Servicer as provided in Section 6.01 hereof."
},
{
  "id": "c049",
  "name": "Affected Party",
  "text": "Affected Party: An “Affected Party” as defined in the Swap Agreement."
},
{
  "id": "c050",
  "name": "Agreement",
  "text": "Agreement: This Pooling and Servicing Agreement and any and all amendments or supplements hereto made in accordance with the terms herein."
},
{
  "id": "c051",
  "name": "Annual Statement of Compliance",
  "text": "Annual Statement of Compliance: As defined in Section 4.16."
},
{
  "id": "c052",
  "name": "Applied Realized Loss Amount",
  "text": "Applied Realized Loss Amount: With respect to any Distribution Date and a Class of Class M Certificates and Class B Certificates, the sum of the Realized Losses with respect to the Mortgage Loans which have been applied in reduction of the Certificate Principal Balance of a 9 [TPW: NYLEGAL:691857.8] 17297-00533 11/15/2007 06:00 PM Class of Certificates pursuant to Section 6.05 of this Agreement which have not previously been reimbursed or reduced by any Subsequent Recoveries applied to such Applied Realized Loss Amount."
},
{
  "id": "c053",
  "name": "Appraised Value",
  "text": "Appraised Value: With respect to any Mortgage Loan originated in connection with a refinancing, the appraised value of the Mortgaged Property based upon the appraisal made at the time of such refinancing or, with respect to any other Mortgage Loan, the lesser of (x) the appraised value of the Mortgaged Property based upon the appraisal made by a fee appraiser at the time of the origination of the related Mortgage Loan, and (y) the sales price of the Mortgaged Property at the time of such origination."
},
{
  "id": "c054",
  "name": "Assignment Agreement",
  "text": "Assignment Agreement: Shall mean any of the Wells Fargo Assignment Agreement, the Countrywide Assignment Agreement or the Saxon Assignment Agreement."
},
{
  "id": "c055",
  "name": "Assessment of Compliance",
  "text": "Assessment of Compliance: As defined in Section 4.17."
},
{
  "id": "c056",
  "name": "Attesting Party",
  "text": "Attesting Party: As defined in Section 4.17."
},
{
  "id": "c057",
  "name": "Attestation Report",
  "text": "Attestation Report: As defined in Section 4.17."
},
{
  "id": "c058",
  "name": "Bankruptcy Code",
  "text": "Bankruptcy Code: Title 11 of the United States Code."
},
{
  "id": "c059",
  "name": "Basis Risk Shortfall Carry Forward Amount",
  "text": "Basis Risk Shortfall Carry Forward Amount: With respect to any Distribution Date and any Class of Class A, Class M and Class B Certificates, an amount equal to the sum of (A) if the Pass-Through Rate for such Class for such Distribution Date is limited to the Net Rate Cap, the excess, if any, of (a) the amount of Current Interest that such Class would have been entitled to receive on such Distribution Date had the Pass-Though Rate applicable to such Class been calculated at a per annum rate equal to One-Month LIBOR plus the related Margin, over (b) the amount of Current Interest that such Class received on such Distribution Date and (B) the Basis Risk Shortfall Carry Forward Amount for the previous Distribution Date not previously paid, together with interest thereon at a rate equal to the related Pass-Through Rate (without giving effect to the Net Rate Cap) for the current Distribution Date."
},
{
  "id": "c060",
  "name": "Book-Entry Certificates",
  "text": "Book-Entry Certificates: Any of the Certificates that shall be registered in the name of the Depository or its nominee, the ownership of which is reflected on the books of the Depository or on the books of a person maintaining an account with the Depository (directly, as a “Depository Participant”, or indirectly, as an indirect participant in accordance with the rules of the Depository and as described in Section 7.06). As of the Closing Date, each Class of Offered Certificates and the Class B-4 Certificates constitutes a Class of Book-Entry Certificates."
},
{
  "id": "c061",
  "name": "Bring Down Agreements",
  "text": "Bring Down Agreements: Any of the following: (i) the Assignment and Recognition Agreement, dated as of the Closing Date, among EMC, Accredited and the Depositor, together with the Third Amended and Restated Mortgage Loan Purchase and Warranties Agreement, dated as of February 1, 2004, as amended by Amendment No. 1, dated as of April 2, 2004, the Seventh Amended and Restated Mortgage Loan Purchase and Warranties Agreement, dated as of June 1, 2006, and the Eighth Amended and Restated Mortgage Loan Purchase and Warranties Agreement, dated as of August 1, 2006, each between the Sponsor and Accredited, (ii) the Bring Down Letter Agreement, dated as of the Closing Date, among WMC and EMC, together with the 10 [TPW: NYLEGAL:69 1857.8] 17297-00533 11/15/2007 06:00 PM Fifth Amended and Restated Mortgage Loan Purchase and Warranties Agreement, dated as of November 1, 2006, and the Sixth Amended and Restated Mortgage Loan Purchase and Warranties Agreement, dated as of February 1, 2007, each between the Sponsor and WMC and (iii) the Bring Down Letter Agreement, dated as of the Closing Date, between Fremont and the Sponsor, together with the Second Amended and Restated Mortgage Loan Purchase and Warranties Agreement, dated as of November 1, 2006, by and between the Sponsor and Fremont, in each case whereby the related Originator made certain representations and warranties with respect to the related Mortgage Loans which were assigned to the Trustee on behalf of the Certificateholders."
},
{
  "id": "c062",
  "name": "Business Day",
  "text": "Business Day: Any day other than (i) a Saturday or a Sunday, or (ii) a day on which banking institutions in The City of New York, New York, Columbia, Maryland, Minneapolis, Minnesota or the city in which the Corporate Trust Office of the Trustee or the Securities Administrator or the principal office of the Master Servicer is located are authorized or obligated by law or executive order to be closed."
},
{
  "id": "c063",
  "name": "Certificate",
  "text": "Certificate: Any one of the certificates of any Class executed and authenticated by the Securities Administrator in substantially the forms attached hereto as Exhibits A-1 through A-6."
},
{
  "id": "c064",
  "name": "Certificateholder or Holder",
  "text": "Certificateholder or Holder: The person in whose name a Certificate is registered in the Certificate Register (initially, Cede & Co., as nominee for the Depository, in the case of any Book-Entry Certificates)."
},
{
  "id": "c065",
  "name": "Certificate Owner",
  "text": "Certificate Owner: With respect to a Book-Entry Certificate, the Person that is the beneficial owner of such Book-Entry Certificate."
},
{
  "id": "c066",
  "name": "Certificate Principal Balance",
  "text": "Certificate Principal Balance: As to any Certificate (other than the Class P Certificates, the Class CE Certificates or the Class R Certificates) and as of any Distribution Date, the Initial Certificate Principal Balance of such Certificate plus any Subsequent Recoveries added to the Certificate Principal Balance of such Certificate pursuant to Section 5.04(b), less the sum of (i) all amounts distributed with respect to such Certificate in reduction of the Certificate Principal Balance thereof on previous Distribution Dates pursuant to Section 6.04, and (ii) any Applied Realized Loss Amounts allocated to such Certificate on previous Distribution Dates. As to the Class CE Certificates and as of any Distribution Date, an amount equal to the Uncertificated Principal Balance of the Class CE Interest. As to the Class P Certificates and as of any Distribution Date, the Initial Certificate Principal Balance of such Certificate less the sum of all amounts distributed with respect to such Certificate in reduction of the Certificate Principal Balance thereof on previous Distribution Dates pursuant to Section 6.08."
},
{
  "id": "c067",
  "name": "Certificate Register",
  "text": "Certificate Register: The register maintained pursuant to Section 7.02 hereof."
},
{
  "id": "c068",
  "name": "Class",
  "text": "Class: All Certificates bearing the same Class designation as set forth in Section 7.01 hereof."
},
{
  "id": "c069",
  "name": "Class A Certificate",
  "text": "Class A Certificate: Any of the Class A-1, Class A-2, Class A-3 and Class A-4 Certificates."
},
{
  "id": "c070",
  "name": "Class A Principal Distribution Amount",
  "text": "Class -A Principal Distribution Amount: For any Distribution Date, an amount equal to the lesser of (x) the Principal Distribution Amount for such Distribution Date and (y) the excess, if any, of (i) the aggregate Certificate Principal Balance of the Class A Certificates immediately prior to such Distribution Date, over (ii) the lesser of (a) the product of (1) 49.30% and (2) the ageregate Stated Principal Balance of the Mortgage Loans as of the last day of the related Due Period (after giving effect to scheduled payments of principal due during the related Due Period, to the extent received or advanced, and unscheduled collections of principal received during the related Prepayment Period, and after reduction for Realized Losses incurred during the related Prepayment Period), and (b) the aggregate Stated Principal Balance of the Mortgage Loans as of the last day of the related Due Period (after giving effect to scheduled payments of principal due during the related Due Period, to the extent received or advanced, and unscheduled collections of principal received during the related Prepayment Period, and after reduction for Realized Losses incurred during the related Prepayment Period) minus $3,675,502."
},
{
  "id": "c071",
  "name": "Class A-1 Certificate",
  "text": "Class A-1 Certificate: Any Certificate designated as a “Class A-1 Certificate” on the face thereof, in the form of Exhibit A-1 hereto, representing the right to the Percentage Interest of distributions provided for the Class A-1 Certificates as set forth herein and evidencing (i) a Regular Interest in REMIC III, (ii) the right to receive Basis Risk Shortfall Carry Forward Amounts and (iii) the obligation to pay Class IO Distribution Amounts."
},
{
  "id": "c072",
  "name": "Class A-1 Pass-Through Rate",
  "text": "Class A-1 Pass-Through Rate: Shall mean (i) on any Distribution Date which occurs on or prior to the Optional Termination Date, One-Month LIBOR plus 0.080% per annum and (ii) for each Distribution Date thereafter, One-Month LIBOR plus 0.160% per annum, in each case subject to a cap equal to the related Net Rate Cap for such Distribution Date."
},
{
  "id": "c073",
  "name": "Class A-2 Certificate",
  "text": "Class A-2 Certificate: Any Certificate designated as a “Class A-2 Certificate” on the face thereof, in the form of Exhibit A-1 hereto, representing the right to the Percentage Interest of distributions provided for the Class A-2 Certificates as set forth herein and evidencing (i) a Regular Interest in REMIC III, (ii) the right to receive Basis Risk Shortfall Carry Forward Amounts and (iii) the obligation to pay Class IO Distribution Amounts."
},
{
  "id": "c074",
  "name": "Class A-2 Pass-Through Rate",
  "text": "Class A-2 Pass-Through Rate: Shall mean (i) on any Distribution Date which occurs on or prior to the Optional Termination Date, One-Month LIBOR plus 0.190% per annum and (ii) for each Distribution Date thereafter, One-Month LIBOR plus 0.380% per annum, in each case subject to a cap equal to the related Net Rate Cap for such Distribution Date."
},
{
  "id": "c075",
  "name": "Class A-3 Certificate",
  "text": "Class A-3 Certificate: Any Certificate designated as a “Class A-3 Certificate” on the face thereof, in the form of Exhibit A-1 hereto, representing the right to the Percentage Interest of distributions provided for the Class A-2 Certificates as set forth herein and evidencing (i) a Regular Interest in REMIC III, (ii) the right to receive Basis Risk Shortfall Carry Forward Amounts and (111) the obligation to pay Class IO Distribution Amounts."
},
{
  "id": "c076",
  "name": "Class A-3 Pass-Through Rate",
  "text": "Class A-3 Pass-Through Rate: Shall mean (i) on any Distribution Date which occurs on or prior to the Optional Termination Date, One-Month LIBOR plus 0.230% per annum and (11) for each Distribution Date thereafter, One-Month LIBOR plus 0.460% per annum, in each case subject to a cap equal to the related Net Rate Cap for such Distribution Date."
},
{
  "id": "c077",
  "name": "Class A-4 Certificate",
  "text": "Class A-4 Certificate: Any Certificate designated as a “Class A-4 Certificate” on the face thereof, in the form of Exhibit A-1 hereto, representing the right to the Percentage Interest of distributions provided for the Class A-4 Certificates as set forth herein and evidencing (i) a Regular Interest in REMIC IIL, (ii) the right to receive Basis Risk Shortfall Carry Forward Amounts and (iii) the obligation to pay Class IO Distribution Amounts."
},
{
